@app.get("/report")
def get_report() -> Response:
    """Serve the report as raw JSON bytes.

    Returning Response directly guarantees Content-Length equals the exact
    number of body bytes (json.dumps output), with no chunked encoding.
    """
    body = json.dumps(REPORT).encode("utf-8")
    return Response(content=body, media_type="application/json")

