@app.head("/report")
def head_report() -> Response:
    """HEAD must advertise the exact byte count GET will deliver.

    Computes the same payload and returns an empty body carrying only the
    accurate Content-Length header, so probes never see a lying header.
    """
    body = _report_bytes()
    return Response(
        media_type="application/json",
        headers={
            "Content-Length": str(len(body)),
            "X-Report-Bytes": str(len(body)),
        },
    )

